  'proRibbon.groupOtherCodes': 'Otras normas',
  'proRibbon.cmdOtherCodes': 'Verificar barras',
  'proRibbon.cmdOtherCodesDesc': 'Verifica las barras con AISC 360, EN 1993-1-1, AISI S100, ACI 318 o EN 1992-1-1, con las combinaciones activas.',
  'otherCodes.pick': 'Norma',
  'otherCodes.family.steel': 'Acero laminado y tubos',
